import os,json
out={}
p='LOGS/RG_RUN_HISTORY.json'
try:
    data=json.load(open(p,encoding='utf-8'))
    if isinstance(data,dict):
        rows=data.get('runs') or data.get('items') or data.get('history') or []
        out['schema_keys']=list(data.keys())
    else:
        rows=data
    wanted={'886','889','890','891','892','893','898','899'}
    filt=[]
    for x in rows[-1000:]:
        if not isinstance(x,dict): continue
        blob=json.dumps(x,ensure_ascii=False)
        if any(s in blob for s in wanted):
            filt.append(x)
    out['matches']=filt[-120:]
except Exception as e:
    out['error']=repr(e)
print(json.dumps(out,ensure_ascii=False))
